"use client";

import Box from '@mui/material/Box';

export default function BreakpointsAsArray() {
  return (
    <div>
      <Box sx={{ width: [100, 200, 300] }}>This box has a responsive width.</Box>
    </div>
  );
}

"use client";

import Box from '@mui/material/Box';

export default function BreakpointsAsObject() {
  return (
    <div>
      <Box
        sx={{
          width: {
            xs: 100, // theme.breakpoints.up('xs')
            sm: 200, // theme.breakpoints.up('sm')
            md: 300, // theme.breakpoints.up('md')
            lg: 400, // theme.breakpoints.up('lg')
            xl: 500, // theme.breakpoints.up('xl')
          },
        }}
      >
        This box has a responsive width.
      </Box>
    </div>
  );
}

"use client";

import Box from '@mui/material/Box';
import { Theme } from '@mui/material/styles';

export default function ValueAsFunction() {
  return (
    <div>
      <Box
        sx={{
          p: 1,
          border: 1,
          borderColor: (theme: Theme) => theme.palette.primary.main,
        }}
      >
        Border color with theme value.
      </Box>
    </div>
  );
}

"use client";

import TrendingUpIcon from '@mui/icons-material/TrendingUp';
import Box from '@mui/system/Box';

export default function Why() {
  return (
    <Box
      sx={{
        p: 2,
        minWidth: 300,
        border: '1px solid',
        borderColor: 'divider',
        bgcolor: 'background.default',
        borderRadius: 2,
      }}
    >
      <Box sx={{ color: 'text.secondary' }}>Sessions</Box>
      <Box
        sx={{ color: 'text.primary', fontSize: '2.125rem', fontWeight: 'medium' }}
      >
        98.3 K
      </Box>
      <Box
        component={TrendingUpIcon}
        sx={{ color: 'success.dark', fontSize: '1rem', verticalAlign: 'sub' }}
      />
      <Box
        sx={{
          display: 'inline',
          fontSize: '0.875rem',
          fontWeight: 'bold',
          color: 'success.dark',
          mx: 0.5,
        }}
      >
        18.7%
      </Box>
      <Box sx={{ color: 'text.secondary', display: 'inline', fontSize: '0.875rem' }}>
        vs. last week
      </Box>
    </Box>
  );
}

